WITH cleaned AS (SELECT *, CAST(is_flagged AS INT) AS is_flagged_flag, COALESCE(merchant, 'NONE') AS merchant_clean FROM transactions WHERE merchant IS DISTINCT FROM 'Grab' AND merchant NOT IN ('Lazada', 'Amazon', 'Grab')) SELECT s.id, s.account_id, s.amount, s.txn_time, s.is_flagged_flag, s.merchant_clean, a.balance FROM cleaned s INNER JOIN accounts a ON s.account_id = a.id WHERE a.balance <= 75000;
